command:
set -euo pipefail; env_file="${UA_WHATBOX_ENV_FILE:-${XDG_CONFIG_HOME:-$HOME/.config}/upload-assistant/whatbox.env}"; set -a; source "$env_file"; set +a; export SSHPASS="$UA_WHATBOX_PASSWORD"; sshpass -e ssh -4 -o PubkeyAuthentication=no -o PreferredAuthentications=password -o StrictHostKeyChecking=yes artemisprime@destiny.whatbox.ca bash -s <<'REMOTE'
set -u
cd ~/Upload-Assistant-wastaken
echo paths:
for p in /mnt/mpathf/artemisprime /mnt/mpathf/artemisprime/Upload-Assistant-wastaken/docker-data/data; do if [ -d "$p" ]; then echo "$p=present"; else echo "$p=missing"; fi; done
echo qbit-settings:
grep -nE '"qbit_(url|port|use_proxy|category)"' docker-data/data/config.py || true
echo service-state:
podman inspect upload-assistant-wastaken --format 'status={{.State.Status}} health={{if .State.Healthcheck}}{{.State.Healthcheck.Status}}{{else}}unavailable{{end}}' 2>/dev/null || true
REMOTE
